import numpy as np
from scipy import ndimage as nd
from scipy.spatial import cKDTree
from PIL import Image, ImageDraw
SCALE=.227185/1024

def contours(mask):
    # Oriented boundary cycles of the union of foreground pixel squares.
    a=np.pad(np.asarray(mask,bool),1)
    edges={}
    def put(x,y,dx,dy):
        p=(int(x),int(y));q=(int(x+dx),int(y+dy))
        edges.setdefault(p,[]).append(q)
    v,u=np.where(a[1:-1,1:-1]&~a[:-2,1:-1])
    for y,x in zip(v,u):put(x,y,1,0)
    v,u=np.where(a[1:-1,1:-1]&~a[1:-1,2:])
    for y,x in zip(v,u):put(x+1,y,0,1)
    v,u=np.where(a[1:-1,1:-1]&~a[2:,1:-1])
    for y,x in zip(v,u):put(x+1,y+1,-1,0)
    v,u=np.where(a[1:-1,1:-1]&~a[1:-1,:-2])
    for y,x in zip(v,u):put(x,y+1,0,-1)
    loops=[]
    while edges:
        start=next(iter(edges));cur=start;prev=(start[0]-1,start[1]);path=[]
        while True:
            path.append(cur)
            cand=edges[cur]
            if len(cand)>1:
                direction=np.array(cur)-prev
                scores=[np.cross(direction,np.array(q)-cur) for q in cand]
                j=int(np.argmax(scores))
            else:j=0
            nxt=cand.pop(j)
            if not cand:del edges[cur]
            prev,cur=cur,nxt
            if cur==start:break
        path.append(start)
        loops.append(np.asarray(path,float)-.5)
    return sorted(loops,key=len,reverse=True)

def simplify(p,eps=.5):
    if len(p)<=2:return p
    d=p[-1]-p[0];den=np.dot(d,d)
    if den==0:dist=np.linalg.norm(p-p[0],axis=1)
    else:
        t=np.clip((p-p[0])@d/den,0,1)
        dist=np.linalg.norm(p-(p[0]+t[:,None]*d),axis=1)
    k=np.argmax(dist)
    if dist[k]<=eps:return p[[0,-1]]
    return np.vstack([simplify(p[:k+1],eps)[:-1],simplify(p[k:],eps)])

def rings_for_mask(mask,inset=3.,spacing=4.):
    dt=nd.distance_transform_edt(mask)
    rings=[]
    depth=inset
    while depth<=dt.max():
        for c in contours(dt>=depth):
            if len(c)>4:
                c=simplify(c,.4)
                # Smooth pixel-scale staircase, staying close to inset contour.
                rings.append({'depth':depth,'p':c})
        depth+=spacing
    return rings

if __name__=='__main__':
    m=np.array(Image.open('/app/target.png')).mean(2)<80
    lab,n=nd.label(m)
    for i in range(1,n+1):
        rr=rings_for_mask(lab==i)
        print(i,'rings',len(rr),'length_mm',sum(np.linalg.norm(np.diff(x['p'],axis=0),axis=1).sum() for x in rr)*SCALE*1000)
    im=Image.open('/app/target.png');draw=ImageDraw.Draw(im)
    for c in rings_for_mask(lab==1):draw.line([tuple(v) for v in c['p']],fill=(255,20,30),width=1)
    im.save('/app/output/rings.png')
